    // A's commit falls back to A alone.
    a.dispatch({ type: 'submit-settled', attempt, ok: true })
    expect(a.state).toMatchObject({ phase: 'plain', draft: '' })
    expect(b.state).toMatchObject({ phase: 'claimed', draft: '/model ' })
  })
})

